begin read only;
select jsonb_build_object(
  'role', (select jsonb_build_object('name',rolname,'bypassrls',rolbypassrls,'superuser',rolsuper,'inherit',rolinherit) from pg_roles where rolname='service_role'),
  'schema_usage',has_schema_privilege('service_role','public','USAGE'),
  'table_privileges',(select jsonb_agg(jsonb_build_object('table',c.relname,'select',has_table_privilege('service_role',c.oid,'SELECT'),'insert',has_table_privilege('service_role',c.oid,'INSERT'),'update',has_table_privilege('service_role',c.oid,'UPDATE'),'delete',has_table_privilege('service_role',c.oid,'DELETE'),'truncate',has_table_privilege('service_role',c.oid,'TRUNCATE')) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','v')),
  'worker_functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'execute',has_function_privilege('service_role',p.oid,'EXECUTE'),'definer',p.prosecdef,'owner',r.rolname,'settings',p.proconfig) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner where n.nspname='public' and p.proname in ('claim_notification_jobs','validate_notification_job','complete_notification_job','notification_webhook','notification_job_state')),
  'direct_sequence_privileges',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and case when c.relkind='S' then has_sequence_privilege('service_role',c.oid,'USAGE,SELECT,UPDATE') else false end),
  'unexpected_worker_execute',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and has_function_privilege('service_role',p.oid,'EXECUTE') and p.proname not in ('claim_notification_jobs','validate_notification_job','complete_notification_job','notification_webhook','notification_job_state') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
  'public_application_execute',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where n.nspname='public' and a.grantee=0 and a.privilege_type='EXECUTE' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
  'default_acl',(select jsonb_agg(jsonb_build_object('creator',r.rolname,'schema',coalesce(n.nspname,'all'),'type',a.defaclobjtype,'acl',a.defaclacl::text) order by r.rolname,coalesce(n.nspname,'all'),a.defaclobjtype) from pg_default_acl a join pg_roles r on r.oid=a.defaclrole left join pg_namespace n on n.oid=a.defaclnamespace where r.rolname='postgres' and (n.nspname='public' or a.defaclnamespace=0))
) as privileges;
commit;
